from __future__ import annotations

import builtins
import os
import re
import shutil
import subprocess
import sys
from contextlib import contextmanager
from functools import lru_cache
from pathlib import Path
from typing import Any, Iterator


def torch_package_dir() -> Path:
    """Engine site-packages torch dir (does not import torch)."""
    win = Path(sys.prefix) / "Lib" / "site-packages" / "torch"
    if win.is_dir():
        return win
    py = f"python{sys.version_info.major}.{sys.version_info.minor}"
    return Path(sys.prefix) / "lib" / py / "site-packages" / "torch"


def read_torch_version() -> str:
    """Installed torch version from metadata / version.py — never LoadLibrary."""
    try:
        from importlib.metadata import version

        return str(version("torch") or "").strip()
    except Exception:
        pass
    version_py = torch_package_dir() / "version.py"
    if not version_py.is_file():
        return ""
    try:
        text = version_py.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return ""
    for line in text.splitlines():
        if line.startswith("__version__"):
            parts = line.split("=", 1)
            if len(parts) == 2:
                return parts[1].strip().strip("'\"").strip()
    return ""


def torch_cuda_libs_present() -> bool:
    """True when a CUDA torch wheel is on disk (c10_cuda), without loading it.

    Importing torch / calling torch.cuda.is_available() loads unsigned CUDA DLLs
    and can freeze Windows (Smart App Control / WDAC scan, or CUDA driver init).
    UI probes (model picker, GPU status fallback) must use this instead.
    """
    lib = torch_package_dir() / "lib"
    if os.name == "nt":
        return (lib / "c10_cuda.dll").is_file()
    return any(lib.glob("libc10_cuda.so*"))


def nvidia_driver_present() -> bool:
    """Cheap NVIDIA-driver presence check (no torch, no CUDA context)."""
    if shutil.which("nvidia-smi"):
        return True
    if os.name == "nt":
        sys32 = Path(os.environ.get("SystemRoot", r"C:\Windows")) / "System32"
        return (sys32 / "nvcuda.dll").is_file() or (sys32 / "nvml.dll").is_file()
    return Path("/usr/lib/x86_64-linux-gnu/libcuda.so.1").is_file()


_RE_BLACKWELL_GPU = re.compile(
    r"(?:RTX\s*50\d{2}|BLACKWELL|GB20\d|B100|B200)",
    re.IGNORECASE,
)
_RE_NVIDIA_SMI_CUDA = re.compile(
    r"CUDA\s+(?:UMD\s+)?Version:\s*([\d.]+)",
    re.IGNORECASE,
)
_TORCH_CUDA_MODERN_MARKERS = (
    "+cu128",
    "+cu129",
    "+cu130",
    "+cu131",
    "+cu132",
    "+cu133",
)


@lru_cache(maxsize=1)
def probe_gpu_compute_cap() -> float:
    """First GPU compute capability (e.g. 8.9, 12.0) via nvidia-smi — no torch."""
    if not shutil.which("nvidia-smi"):
        return 0.0
    try:
        out = subprocess.check_output(
            ["nvidia-smi", "--query-gpu=compute_cap", "--format=csv,noheader"],
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=5,
            stderr=subprocess.DEVNULL,
        )
        line = (out or "").strip().splitlines()[0] if out.strip() else ""
        return float(str(line).strip())
    except Exception:
        return 0.0


def needs_torch_cuda128(gpu_name: str | None = None) -> bool:
    """
    Blackwell (RTX 50xx, sm_120) needs PyTorch built with CUDA 12.8+.

    cu126 wheels only ship kernels up to sm_90 and fail at runtime with
    ``cudaErrorNoKernelImageForDevice`` on RTX 5080 / 5090 class GPUs.
    """
    cap = probe_gpu_compute_cap()
    if cap >= 12.0:
        return True
    name = str(gpu_name or "").strip()
    if not name and shutil.which("nvidia-smi"):
        try:
            out = subprocess.check_output(
                ["nvidia-smi", "--query-gpu=name", "--format=csv,noheader"],
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=5,
                stderr=subprocess.DEVNULL,
            )
            line = (out or "").strip().splitlines()[0] if out.strip() else ""
            name = str(line).strip()
        except Exception:
            name = ""
    return bool(name and _RE_BLACKWELL_GPU.search(name))


@lru_cache(maxsize=1)
def probe_driver_cuda_version() -> str:
    """Driver-reported CUDA capability (e.g. ``12.6``, ``13.3``) from nvidia-smi."""
    if not shutil.which("nvidia-smi"):
        return ""
    try:
        out = subprocess.check_output(
            ["nvidia-smi"],
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=5,
            stderr=subprocess.DEVNULL,
        )
        for line in str(out or "").splitlines():
            m = _RE_NVIDIA_SMI_CUDA.search(line)
            if m:
                return str(m.group(1) or "").strip()
    except Exception:
        pass
    return ""


@lru_cache(maxsize=1)
def probe_driver_cuda_major() -> int:
    ver = probe_driver_cuda_version()
    if not ver:
        return 0
    try:
        return int(str(ver).split(".", 1)[0])
    except Exception:
        return 0


def _is_modern_torch_cuda_tag(tag: str) -> bool:
    t = str(tag or "").strip().lower()
    if not t or t == "cpu":
        return False
    if t.startswith("cu13"):
        return True
    return t in ("cu128", "cu129")


def resolve_torch_cuda_variant(
    *,
    gpu_name: str | None = None,
    driver_cuda_major: int | None = None,
) -> str:
    """
    Pick pinned PyTorch CUDA wheel tag for this machine.

    - Blackwell (RTX 50xx): cu130 when driver CUDA 13+, else cu128
    - Older NVIDIA: cu126
    """
    name = str(gpu_name or "").strip()
    if needs_torch_cuda128(name if name else None):
        major = (
            int(driver_cuda_major)
            if driver_cuda_major is not None
            else probe_driver_cuda_major()
        )
        if major >= 13:
            return "cu130"
        return "cu128"
    return "cu126"


def installed_torch_cuda_tag() -> str:
    """CUDA tag from installed torch metadata (e.g. ``cu126``), or empty."""
    ver = read_torch_version()
    if not ver:
        return ""
    low = ver.lower()
    for marker in _TORCH_CUDA_MODERN_MARKERS:
        if marker in low:
            return marker.lstrip("+")
    if "+cu126" in low:
        return "cu126"
    if "+cu124" in low:
        return "cu124"
    if "+cpu" in low:
        return "cpu"
    return ""


def torch_cuda_variant_mismatch() -> bool:
    """
    True when this GPU needs a modern CUDA torch and the install is missing or wrong.

    Blackwell (RTX 50xx) requires cu128/cu130. Missing wheels, CPU-only torch, or
    older CUDA tags (e.g. cu126) all count so UI can prompt「补齐 CUDA PyTorch」.
    """
    if not needs_torch_cuda128():
        return False
    if not torch_cuda_libs_present():
        return True
    tag = installed_torch_cuda_tag()
    if not tag or tag == "cpu":
        return True
    return not _is_modern_torch_cuda_tag(tag)


def torch_cuda_suitable_for_gpu() -> tuple[bool, str]:
    """
    Best-effort: installed CUDA torch matches GPU arch (filesystem probe only).

    ROCm wheels expose the GPU through ``torch.cuda`` but ship HIP libs
    (``c10_hip.dll``), not ``c10_cuda.dll``. Those are suitable on AMD.

    Returns (ok, note). Does not import torch unless mismatch already known.
    """
    try:
        from .rocm_device import amd_gpu_present, torch_rocm_libs_present

        if torch_rocm_libs_present() and (amd_gpu_present() or not nvidia_driver_present()):
            return True, ""
    except Exception:
        pass
    if not torch_cuda_libs_present():
        return False, "未安装 CUDA 版 PyTorch"
    if torch_cuda_variant_mismatch():
        want = resolve_torch_cuda_variant()
        have = installed_torch_cuda_tag() or "cpu"
        return (
            False,
            f"当前 PyTorch（{have}）不支持本机 Blackwell GPU，需要 {want}（CUDA 12.8+ / 13.x）",
        )
    return True, ""


def detect_device() -> dict[str, Any]:
    """Best-effort hardware probe for recommend profiles."""
    info: dict[str, Any] = {
        "hasCuda": False,
        "vramMb": 0,
        "ramMb": 0,
        "gpuName": "",
        "device": "cpu",
        "cublas12": False,
        "cublas13": False,
    }
    try:
        import psutil  # type: ignore

        info["ramMb"] = int(psutil.virtual_memory().total / (1024 * 1024))
    except Exception:
        # Fallback rough estimate unused; recommend still works with defaults
        pass

    if shutil.which("nvidia-smi"):
        try:
            out = subprocess.check_output(
                [
                    "nvidia-smi",
                    "--query-gpu=name,memory.total",
                    "--format=csv,noheader,nounits",
                ],
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=5,
                stderr=subprocess.DEVNULL,
            )
            line = (out or "").strip().splitlines()[0] if out.strip() else ""
            if line:
                parts = [p.strip() for p in line.split(",")]
                if len(parts) >= 2:
                    info["gpuName"] = parts[0]
                    info["vramMb"] = int(float(parts[1]))
                    info["hasCuda"] = True
                    info["device"] = "cuda"
        except Exception:
            pass

    if not info["hasCuda"] and nvidia_driver_present():
        # Driver exists but nvidia-smi query failed. Do not import torch here:
        # loading CUDA DLLs can hang the machine under Smart App Control / WDAC.
        info["hasCuda"] = True
        info["device"] = "cuda"

    info["cublas12"] = bool(find_cublas64_12())
    info["cublas13"] = bool(find_cublas64_13())
    info["computeCap"] = probe_gpu_compute_cap()
    info["driverCudaVersion"] = probe_driver_cuda_version()
    info["driverCudaMajor"] = probe_driver_cuda_major()
    info["needsTorchCuda128"] = bool(needs_torch_cuda128(info.get("gpuName") or ""))
    info["torchCudaVariant"] = resolve_torch_cuda_variant(
        gpu_name=info.get("gpuName") or "",
        driver_cuda_major=int(info["driverCudaMajor"] or 0),
    )
    try:
        from .rocm_device import probe_amd_gpu

        amd = probe_amd_gpu() if not info["hasCuda"] else {}
    except Exception:
        amd = {}
    info["hasRocm"] = bool(amd.get("name"))
    info["rocmGfx"] = str(amd.get("gfx") or "") if info["hasRocm"] else ""
    if info["hasRocm"]:
        # ROCm PyTorch exposes the device as torch.cuda — keep device="cuda" so
        # recommend / job paths treat the card as a usable accelerator.
        if not info.get("gpuName"):
            info["gpuName"] = str(amd.get("name") or "")
        try:
            amd_vram = int(amd.get("vramMb") or 0)
        except Exception:
            amd_vram = 0
        if amd_vram > 0 and int(info.get("vramMb") or 0) <= 0:
            info["vramMb"] = amd_vram
        info["device"] = "cuda"
    return info


@lru_cache(maxsize=1)
def find_cublas64_12() -> str:
    """
    Locate CUDA 12 cuBLAS DLL required by CTranslate2 / faster-whisper on Windows.
    Returns absolute path or empty string.
    """
    name = "cublas64_12.dll" if os.name == "nt" else "libcublas.so.12"

    # Explicit env override
    override = str(os.environ.get("CUBLAS64_12") or os.environ.get("TRANSUB_CUBLAS12") or "").strip()
    if override and Path(override).is_file():
        return str(Path(override).resolve())

    search_dirs: list[Path] = []
    for key in (
        "CUDA_PATH",
        "CUDA_PATH_V12_9",
        "CUDA_PATH_V12_8",
        "CUDA_PATH_V12_6",
        "CUDA_PATH_V12_5",
        "CUDA_PATH_V12_4",
        "CUDA_PATH_V12_3",
        "CUDA_PATH_V12_2",
        "CUDA_PATH_V12_1",
        "CUDA_PATH_V12_0",
    ):
        root = str(os.environ.get(key) or "").strip()
        if root:
            search_dirs.append(Path(root) / ("bin" if os.name == "nt" else "lib64"))

    for part in str(os.environ.get("PATH") or "").split(os.pathsep):
        if part.strip():
            search_dirs.append(Path(part.strip()))

    if os.name == "nt":
        base = Path(r"C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA")
        if base.is_dir():
            for child in sorted(base.glob("v12*"), reverse=True):
                search_dirs.append(child / "bin")
            for child in sorted(base.glob("v13*"), reverse=True):
                search_dirs.append(child / "bin")
        # nvidia-cublas-cu12 / cu13 wheel layout
        try:
            import site

            for sp in site.getsitepackages() + [site.getusersitepackages()]:
                if not sp:
                    continue
                search_dirs.append(Path(sp) / "nvidia" / "cublas" / "bin")
                search_dirs.append(Path(sp) / "nvidia" / "cublas" / "lib")
                search_dirs.append(Path(sp) / "nvidia" / "cu12" / "bin")
                search_dirs.append(Path(sp) / "nvidia" / "cu12" / "bin" / "x86_64")
                search_dirs.append(Path(sp) / "nvidia" / "cu13" / "bin")
                search_dirs.append(Path(sp) / "nvidia" / "cu13" / "bin" / "x86_64")
        except Exception:
            pass

    seen: set[str] = set()
    preferred = ""
    torch_fallback = ""
    for directory in search_dirs:
        try:
            key = str(directory.resolve()).lower()
        except Exception:
            key = str(directory).lower()
        if key in seen:
            continue
        seen.add(key)
        candidate = directory / name
        if not candidate.is_file():
            continue
        resolved = str(candidate.resolve())
        # Prefer nvidia / Toolkit cuBLAS over torch\\lib (CT2 cannot load the latter
        # reliably when both are present — WinError 999 / "cannot be loaded").
        norm = resolved.lower().replace("/", "\\")
        if "\\torch\\lib\\" in norm:
            if not torch_fallback:
                torch_fallback = resolved
            continue
        preferred = resolved
        break
    return preferred or torch_fallback


@lru_cache(maxsize=1)
def find_cublas64_13() -> str:
    """
    Locate CUDA 13 cuBLAS DLL (onnxruntime-gpu >= 1.27 on Windows).
    Returns absolute path or empty string.
    """
    name = "cublas64_13.dll" if os.name == "nt" else "libcublas.so.13"

    override = str(os.environ.get("CUBLAS64_13") or os.environ.get("TRANSUB_CUBLAS13") or "").strip()
    if override and Path(override).is_file():
        return str(Path(override).resolve())

    search_dirs: list[Path] = []
    for key in (
        "CUDA_PATH",
        "CUDA_PATH_V13_2",
        "CUDA_PATH_V13_1",
        "CUDA_PATH_V13_0",
    ):
        root = str(os.environ.get(key) or "").strip()
        if root:
            search_dirs.append(Path(root) / ("bin" if os.name == "nt" else "lib64"))

    for part in str(os.environ.get("PATH") or "").split(os.pathsep):
        if part.strip():
            search_dirs.append(Path(part.strip()))

    if os.name == "nt":
        base = Path(r"C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA")
        if base.is_dir():
            for child in sorted(base.glob("v13*"), reverse=True):
                search_dirs.append(child / "bin")
        try:
            import site

            for sp in site.getsitepackages() + [site.getusersitepackages()]:
                if not sp:
                    continue
                search_dirs.append(Path(sp) / "nvidia" / "cublas" / "bin")
                search_dirs.append(Path(sp) / "nvidia" / "cublas" / "lib")
                search_dirs.append(Path(sp) / "nvidia" / "cu13" / "bin")
                search_dirs.append(Path(sp) / "nvidia" / "cu13" / "bin" / "x86_64")
        except Exception:
            pass

    seen: set[str] = set()
    for directory in search_dirs:
        try:
            key = str(directory.resolve()).lower()
        except Exception:
            key = str(directory).lower()
        if key in seen:
            continue
        seen.add(key)
        candidate = directory / name
        if candidate.is_file():
            return str(candidate.resolve())
    return ""


def ensure_cublas12_on_path() -> bool:
    """Prepend cuBLAS directory to PATH when found. Returns True if DLL is available."""
    dll = find_cublas64_12()
    if not dll:
        return False
    directory = str(Path(dll).parent)
    path_env = os.environ.get("PATH", "")
    parts = path_env.split(os.pathsep) if path_env else []
    if directory not in parts:
        os.environ["PATH"] = directory + (os.pathsep + path_env if path_env else "")
    return True


def ctranslate2_cuda_usable() -> bool:
    """True when CT2 sees a GPU *and* CUDA 12 cuBLAS can be loaded.

    On Windows, nvidia/cublas bins must be on PATH *before* importing CTranslate2
    or calling get_cuda_device_count(); otherwise CUDA DLL load fails and a later
    PATH fix cannot recover in the same process.
    """
    return bool(ctranslate2_cuda_status().get("ok"))


def ctranslate2_cuda_status(*, live: bool = True) -> dict[str, Any]:
    """Diagnostic status for CT2 CUDA (used by probes / UI hints).

    ``live=False`` only checks package metadata + cublas on disk — never imports
    ctranslate2. UI/status endpoints must use that mode: importing CT2 loads CUDA
    DLLs and can freeze Windows under Smart App Control / WDAC.
    """
    out: dict[str, Any] = {
        "ok": False,
        "reason": "",
        "deviceCount": 0,
        "cublas12": False,
    }
    try:
        from .runtime_gpu import inject_nvidia_lib_path

        inject_nvidia_lib_path()
    except Exception:
        ensure_cublas12_on_path()
    cublas = bool(find_cublas64_12())
    out["cublas12"] = cublas

    if not live:
        try:
            from importlib.metadata import PackageNotFoundError, version

            version("ctranslate2")
        except PackageNotFoundError:
            out["reason"] = "ctranslate2_not_installed"
            return out
        except Exception as err:
            out["reason"] = f"ctranslate2 metadata failed: {err}"
            return out
        if os.name == "nt" and not cublas:
            out["reason"] = "cublas64_12.dll not found after PATH inject"
            return out
        # Actual CUDA device count is verified when a job imports CT2.
        out["ok"] = True
        out["deviceCount"] = -1
        out["reason"] = "package_and_cublas_present"
        return out

    try:
        with soften_torch_cuda_import_failure():
            import ctranslate2 as ct2  # type: ignore

        count = int(ct2.get_cuda_device_count() or 0)
        out["deviceCount"] = count
        if count <= 0:
            out["reason"] = "ctranslate2.get_cuda_device_count()=0"
            return out
    except ModuleNotFoundError:
        out["reason"] = "ctranslate2_not_installed"
        return out
    except Exception as err:
        msg = str(err or "")
        if "No module named" in msg and "ctranslate2" in msg:
            out["reason"] = "ctranslate2_not_installed"
        else:
            out["reason"] = f"ctranslate2 import/init failed: {err}"
        return out
    if os.name == "nt" and not cublas:
        out["reason"] = "cublas64_12.dll not found after PATH inject"
        return out
    out["ok"] = True
    return out


def resolve_ctranslate2_device(device: str = "auto") -> str:
    """
    Pick cpu/cuda for CTranslate2 (Whisper / Opus-CT2).
    Falls back to CPU when NVIDIA driver is present but cublas64_12.dll is missing.
    """
    want = str(device or "auto").strip().lower()
    if want in ("cpu", "cuda"):
        if want == "cpu":
            return "cpu"
        if not ctranslate2_cuda_usable():
            return "cpu"
        return "cuda"
    # auto / gpu / cuda:* …
    if want.startswith("cuda") or want in ("auto", "gpu", ""):
        return "cuda" if ctranslate2_cuda_usable() else "cpu"
    return "cuda" if ctranslate2_cuda_usable() else "cpu"


def wants_gpu_accel(device: str = "auto") -> bool:
    """True when the job asked for GPU (auto/cuda/gpu), False only for explicit CPU."""
    want = str(device or "auto").strip().lower()
    return want not in ("cpu", "none", "disabled")


def resolve_onnx_providers(device: str = "auto") -> tuple[list[str], str, str]:
    """
    Pick ONNX Runtime providers for WhisperSeg (and similar).

    Returns (providers, actual_device_label, note).
    note is non-empty when the user asked for GPU but only CPU EP is available.
    """
    try:
        import onnxruntime as ort  # type: ignore
    except ImportError:
        return (["CPUExecutionProvider"], "cpu", "onnxruntime 未安装")

    # CUDA EP needs nvidia libs on PATH (same wheels as CT2 / faster-whisper).
    if wants_gpu_accel(device):
        try:
            from .runtime_gpu import inject_nvidia_lib_path

            inject_nvidia_lib_path()
        except Exception:
            pass
        # ORT >= 1.21 can preload CUDA/cuDNN DLLs from nvidia-* site-packages.
        try:
            preload = getattr(ort, "preload_dlls", None)
            if callable(preload):
                preload()
        except Exception:
            pass

    available = list(ort.get_available_providers() or [])
    if not wants_gpu_accel(device):
        return (["CPUExecutionProvider"], "cpu", "")

    if "CUDAExecutionProvider" in available:
        return (
            ["CUDAExecutionProvider", "CPUExecutionProvider"],
            "cuda",
            "",
        )

    has_cpu_ort = "CPUExecutionProvider" in available
    # Soft fallback — WhisperSeg still runs on CPU; ASR job continues.
    try:
        from .runtime_gpu import ort_gpu_install_hint

        hint = ort_gpu_install_hint()
    except Exception:
        hint = (
            "安装与本机 CUDA 匹配的 onnxruntime-gpu"
            "（CUDA 12: 'onnxruntime-gpu>=1.21,<1.27'；"
            "CUDA 13: 'onnxruntime-gpu>=1.27'）及对应 nvidia-*-cu12/cu13。"
        )
    note = (
        "WhisperSeg 将回退 CPU（任务可继续，仅 VAD 较慢）。"
        f"要用 GPU：{hint}"
        "当前仅有 CPUExecutionProvider。"
        if has_cpu_ort
        else "onnxruntime 未提供可用 ExecutionProvider"
    )
    return (["CPUExecutionProvider"], "cpu", note)


# Sticky process flags: clearing sys.modules['torch'] after native `_C` mapped
# leaves the next `import torch` raising ``function already has a docstring``.
_TORCH_NATIVE_SEEN = False
_TORCH_IMPORT_OK = False
_TORCH_IMPORT_FAILED_AFTER_NATIVE = False


def is_torch_cublas_load_conflict(err: BaseException | str) -> bool:
    """True when torch fails loading its own cublas (often after CT2 mapped nvidia's).

    WinError 999 / 1114 / "Error loading .../torch/lib/cublas64_12.dll" is not a missing
    Toolkit case — Whisper/CT2 inference does not need torch.
    """
    msg = str(err or "")
    lower = msg.lower().replace("/", "\\")
    if is_torch_reimport_poison_error(msg):
        return False
    if "torch" not in lower or "cublas" not in lower:
        return False
    if "winerror 999" in lower or "[winerror 999]" in lower:
        return True
    if "winerror 1114" in lower or "[winerror 1114]" in lower:
        return True
    winerr = getattr(err, "winerror", None) if isinstance(err, BaseException) else None
    if winerr in (999, 1114):
        return True
    # torch/_load_dll_libraries message shape
    return "error loading" in lower and "torch\\lib" in lower


def is_torch_reimport_poison_error(err: BaseException | str) -> bool:
    """True when re-importing torch after a poisoned sys.modules clear."""
    msg = str(err or "").lower()
    return "already has a docstring" in msg and (
        "torch" in msg or "_has_torch_function" in msg or "docstring" in msg
    )


def _sync_torch_native_flags_from_modules() -> None:
    """Refresh sticky flags from what Python still has mapped."""
    global _TORCH_NATIVE_SEEN
    if sys.modules.get("torch._C") is not None:
        _TORCH_NATIVE_SEEN = True
        return
    mod = sys.modules.get("torch")
    if mod is not None and getattr(mod, "_C", None) is not None:
        _TORCH_NATIVE_SEEN = True


def mark_torch_import_ok() -> None:
    """Record a successful full ``import torch`` in this process."""
    global _TORCH_NATIVE_SEEN, _TORCH_IMPORT_OK, _TORCH_IMPORT_FAILED_AFTER_NATIVE
    _TORCH_NATIVE_SEEN = True
    _TORCH_IMPORT_OK = True
    _TORCH_IMPORT_FAILED_AFTER_NATIVE = False


def mark_torch_import_failed_after_native() -> None:
    """Native `_C` was touched but package import did not complete cleanly."""
    global _TORCH_NATIVE_SEEN, _TORCH_IMPORT_OK, _TORCH_IMPORT_FAILED_AFTER_NATIVE
    _TORCH_NATIVE_SEEN = True
    _TORCH_IMPORT_OK = False
    _TORCH_IMPORT_FAILED_AFTER_NATIVE = True


def is_torch_c_extension_loaded() -> bool:
    """True when torch's native `_C` is mapped in ``sys.modules``.

    Also consults a sticky flag via :func:`is_torch_reimport_poisoned` /
    :func:`clear_partial_torch_modules` so a purged ``torch`` package cannot be
    mistaken for "never loaded". Callers that need a working ``import torch``
    should use :func:`is_torch_fully_imported`.
    """
    _sync_torch_native_flags_from_modules()
    mod = sys.modules.get("torch")
    if mod is not None and getattr(mod, "_C", None) is not None:
        global _TORCH_NATIVE_SEEN, _TORCH_IMPORT_OK
        if not _TORCH_IMPORT_FAILED_AFTER_NATIVE:
            _TORCH_NATIVE_SEEN = True
            _TORCH_IMPORT_OK = True
        return True
    # Extension module alone still counts as native-mapped (do not clear it).
    return sys.modules.get("torch._C") is not None


def is_torch_fully_imported() -> bool:
    """True when ``import torch`` already succeeded and is safe to reuse."""
    if is_torch_reimport_poisoned():
        return False
    mod = sys.modules.get("torch")
    return mod is not None and getattr(mod, "_C", None) is not None


def is_torch_reimport_poisoned() -> bool:
    """True when another ``import torch`` in this process will hit docstring poison."""
    _sync_torch_native_flags_from_modules()
    if _TORCH_IMPORT_FAILED_AFTER_NATIVE:
        return True
    if not _TORCH_NATIVE_SEEN and sys.modules.get("torch._C") is None:
        return False
    mod = sys.modules.get("torch")
    if mod is not None and getattr(mod, "_C", None) is not None and _TORCH_IMPORT_OK:
        return False
    # Native extension was seen, but the package entry is missing/incomplete.
    if mod is None or getattr(mod, "_C", None) is None:
        return bool(_TORCH_NATIVE_SEEN or sys.modules.get("torch._C") is not None)
    return False


def torch_install_hint() -> str:
    """User-facing repair action. AMD machines must not be sent to CUDA wheels."""
    try:
        from .rocm_device import amd_gpu_present

        if amd_gpu_present():
            return "点「自动修复」补齐 ROCm PyTorch（必须装进引擎运行时，系统 pip 无效）"
    except Exception:
        pass
    return "在设置中「补齐 CUDA PyTorch」"


def torch_reimport_poison_message() -> str:
    return (
        "Torch 已在本引擎进程中损坏（function '_has_torch_function' already has a docstring）。"
        "请完全退出 Transub 后重试；桌面端会尝试自动重启引擎。"
        f"若仍失败，{torch_install_hint()}。"
    )


def format_torch_cuda_load_failure(err: BaseException | str | None = None) -> str:
    """User-facing message for Qwen3 / SenseVoice torch import failures.

    Order matters: a first-import WinError 1114/999 often leaves ``torch._C``
    mapped and sets sticky poison *before* this formatter runs. Prefer the
    concrete CUDA/cublas text when the exception still carries it — do not
    mislabel every poisoned process as a docstring reimport.
    """
    detail = str(err or "").strip()
    # Avoid wrapping an already-friendly engine message.
    if detail.startswith("Torch 已在本引擎进程中损坏") or detail.startswith("Torch CUDA 库加载失败"):
        return detail
    # Explicit docstring / reimport poison in the exception text.
    if (err is not None and is_torch_reimport_poison_error(err)) or (
        "already has a docstring" in detail.lower()
    ):
        return torch_reimport_poison_message()
    # First-load cuBLAS conflict (may coexist with sticky poison after `_C` mapped).
    if err is not None and is_torch_cublas_load_conflict(err):
        return (
            "Torch CUDA 库加载失败（WinError 1114/999 · cublas）。"
            f"请完全退出 Transub 后重试；若仍失败，{torch_install_hint()}。"
            "多任务中途若出现此错误，请结束引擎进程后再继续队列。"
        )
    # Sticky poison without a more specific underlying error.
    if is_torch_reimport_poisoned():
        return torch_reimport_poison_message()
    hint = torch_install_hint()
    if detail:
        return f"Torch / CUDA 导入失败：{detail}。请完全退出后重试，或{hint}。"
    return f"Torch / CUDA 导入失败。请完全退出后重试，或{hint}。"


def clear_partial_torch_modules() -> None:
    """Drop incomplete torch imports from sys.modules.

    Must not run after native `_C` has been mapped: the next ``import torch``
    raises ``function already has a docstring``. Also refuse to clear when only
    ``torch._C`` remains (failed import / bad purge left the extension live).
    """
    _sync_torch_native_flags_from_modules()
    if (
        is_torch_c_extension_loaded()
        or is_torch_reimport_poisoned()
        or _TORCH_NATIVE_SEEN
        or sys.modules.get("torch._C") is not None
    ):
        return
    for key in list(sys.modules):
        if key == "torch" or key.startswith("torch."):
            del sys.modules[key]


@contextmanager
def soften_torch_cuda_import_failure(*, skip_torch: bool | None = None) -> Iterator[None]:
    """Avoid torch during CTranslate2 package import (Whisper inference path).

    CT2 4.x always imports converters → specs → torch. On Windows, after
    nvidia-cublas is mapped for CT2's native extension, loading torch's
    bundled cublas64_12.dll often fails with WinError 999 — and LoadLibrary
    can hang for a long time before raising. Whisper only needs CT2;
    model_spec already treats ImportError as torch_is_available=False.

    Default on Windows: skip torch entirely (do not attempt LoadLibrary)
    *unless torch is already fully imported* (Qwen3 / SenseVoice). Tearing
    down a live torch module poisons the next job in the same engine process.

    Elsewhere: map torch OSError → ImportError.
    """
    if skip_torch is None:
        skip_torch = os.name == "nt"
    real_import = builtins.__import__

    def guarded_import(
        name: str,
        globals: Any = None,
        locals: Any = None,
        fromlist: Any = (),
        level: int = 0,
    ):
        root = name.split(".", 1)[0] if isinstance(name, str) else ""
        if root == "torch":
            if skip_torch:
                # Poisoned process: never strip or re-init; Whisper/CT2 can continue
                # without torch.
                if is_torch_reimport_poisoned():
                    raise ImportError(
                        "torch reimport poisoned in this process; "
                        "restart the engine (Whisper/CT2 does not need torch)"
                    )
                # Torch already loaded (Qwen3/SenseVoice). Let CT2 reuse it —
                # never strip sys.modules while `_C` remains mapped.
                if is_torch_fully_imported():
                    return real_import(name, globals, locals, fromlist, level)
                clear_partial_torch_modules()
                raise ImportError(
                    "torch skipped during CTranslate2 import "
                    "(Whisper/CT2 inference does not need it; "
                    "avoids WinError 999 on torch\\\\lib\\\\cublas)"
                )
            try:
                mod = real_import(name, globals, locals, fromlist, level)
                if root == "torch" and name == "torch":
                    mark_torch_import_ok()
                return mod
            except OSError as err:
                _sync_torch_native_flags_from_modules()
                if is_torch_c_extension_loaded() or sys.modules.get("torch._C") is not None:
                    mark_torch_import_failed_after_native()
                else:
                    clear_partial_torch_modules()
                raise ImportError(f"torch CUDA libs unavailable: {err}") from err
            except Exception:
                _sync_torch_native_flags_from_modules()
                if is_torch_c_extension_loaded() or sys.modules.get("torch._C") is not None:
                    mark_torch_import_failed_after_native()
                raise
        return real_import(name, globals, locals, fromlist, level)

    builtins.__import__ = guarded_import  # type: ignore[assignment]
    try:
        yield
    finally:
        builtins.__import__ = real_import  # type: ignore[assignment]


def is_cublas_missing_error(err: BaseException | str) -> bool:
    msg = str(err or "")
    lower = msg.lower()
    # Do not treat torch\\lib\\cublas load failures as "Toolkit missing".
    if is_torch_cublas_load_conflict(err):
        return False
    return (
        "cublas64_12" in lower
        or "cublas64_13" in lower
        or ("cublas" in lower and "not found" in lower)
    )
